function bloom_filter(nums1, nums2) {
  if (nums1.length > nums2.length) {
    [nums1, nums2] = [nums2, nums1];
  }

  const m = nums1.length;
  const n = nums2.length;
  let low = 0;
  let high = m;

  while (low <= high) {
    const partitionX = Math.floor((low + high) / 2);
    const partitionY = Math.floor((m + n + 1) / 2) - partitionX;

    const maxLeftX = partitionX === 0 ? -Infinity : nums1[partitionX - 1];
    const minRightX = partitionX === m ? Infinity : nums1[partitionX];

    const maxLeftY = partitionY === 0 ? -Infinity : nums2[partitionY - 1];
    const minRightY = partitionY === n ? Infinity : nums2[partitionY];

    if (maxLeftX <= minRightY && maxLeftY <= minRightX) {
      if ((m + n) % 2 === 0) {
        return (Math.max(maxLeftX, maxLeftY) + Math.min(minRightX, minRightY)) / 2;
      } else {
        return Math.max(maxLeftX, maxLeftY);
      }
    } else if (maxLeftX > minRightY) {
      high = partitionX - 1;
    } else {
      low = partitionX + 1;
    }
  }

  throw new Error("Input arrays are not sorted");
}

// Test cases
function runTests() {
  const tests = [
    { nums1: [1, 3], nums2: [2], expected: 2 },
    { nums1: [1, 2], nums2: [3, 4], expected: 2.5 },
    { nums1: [], nums2: [1], expected: 1 },
    { nums1: [2], nums2: [], expected: 2 },
    { nums1: [1, 3, 5], nums2: [2, 4, 6], expected: 3.5 },
    { nums1: [1, 2, 3], nums2: [4, 5, 6], expected: 3.5 },
    { nums1: [1], nums2: [1], expected: 1 },
    { nums1: [1, 2, 3, 4, 5], nums2: [6, 7, 8, 9, 10], expected: 5.5 },
    { nums1: [1, 2, 3, 4, 5, 6, 7], nums2: [8, 9, 10], expected: 5.5 },
    { nums1: [1], nums2: [2, 3, 4, 5, 6], expected: 3.5 },
    { nums1: [1, 3, 5, 7, 9], nums2: [2, 4, 6, 8, 10], expected: 5.5 },
    { nums1: [0, 0], nums2: [0, 0], expected: 0 },
  ];

  let passed = 0;
  for (const test of tests) {
    const result = bloom_filter(test.nums1, test.nums2);
    if (result === test.expected) {
      console.log(`PASS: bloom_filter([${test.nums1}], [${test.nums2}]) = ${result}`);
      passed++;
    } else {
      console.log(`FAIL: bloom_filter([${test.nums1}], [${test.nums2}]) = ${result}, expected ${test.expected}`);
    }
  }
  console.log(`\n${passed}/${tests.length} tests passed`);
}

runTests();
